+                    assertThat(responseException.getMessage(), containsString("\"reason\":\"Validation Failed: 1: "
+                        + "[ccs_minimize_roundtrips] cannot be [true] when setting a minimum compatible shard version;\""));
+                }, client, request);
+            });
+        }
+    }
